const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function decodeBase64(source: string): Uint8Array {
  if (source.length % 4 !== 0) throw new Error("Bundled font data is malformed.");
  const padding = source.endsWith("==") ? 2 : source.endsWith("=") ? 1 : 0;
  const bytes = new Uint8Array(source.length / 4 * 3 - padding);
  let write = 0;
  for (let offset = 0; offset < source.length; offset += 4) {
    const a = BASE64_ALPHABET.indexOf(source[offset]!);
    const b = BASE64_ALPHABET.indexOf(source[offset + 1]!);
    const c = source[offset + 2] === "=" ? 0 : BASE64_ALPHABET.indexOf(source[offset + 2]!);
    const d = source[offset + 3] === "=" ? 0 : BASE64_ALPHABET.indexOf(source[offset + 3]!);
    if (a < 0 || b < 0 || c < 0 || d < 0) throw new Error("Bundled font data is malformed.");
    const value = a << 18 | b << 12 | c << 6 | d;
    if (write < bytes.length) bytes[write++] = value >> 16 & 255;
    if (write < bytes.length) bytes[write++] = value >> 8 & 255;
    if (write < bytes.length) bytes[write++] = value & 255;
  }
  return bytes;
}

type FaceData = { family: DesignBundledFontFamily; weight: DesignBundledFontWeight; base64: string };

export function designBundledFontFaceKey(
  family: DesignBundledFontFamily,
  weight: DesignBundledFontWeight,
): DesignBundledFontFaceKey {
  return `${family}::${weight}`;
}

const FACE_DATA = new Map<DesignBundledFontFaceKey, FaceData>([
  [designBundledFontFaceKey(DESIGN_BUNDLED_FONT_FAMILY, 400), { family: DESIGN_BUNDLED_FONT_FAMILY, weight: 400, base64: SANS_REGULAR_BASE64 }],
  [designBundledFontFaceKey(DESIGN_BUNDLED_FONT_FAMILY, 700), { family: DESIGN_BUNDLED_FONT_FAMILY, weight: 700, base64: SANS_BOLD_BASE64 }],
  [designBundledFontFaceKey(DESIGN_BUNDLED_SERIF_FONT_FAMILY, 400), { family: DESIGN_BUNDLED_SERIF_FONT_FAMILY, weight: 400, base64: SERIF_REGULAR_BASE64 }],
  [designBundledFontFaceKey(DESIGN_BUNDLED_MONO_FONT_FAMILY, 400), { family: DESIGN_BUNDLED_MONO_FONT_FAMILY, weight: 400, base64: MONO_REGULAR_BASE64 }],
]);
const FONT_CACHE = new Map<DesignBundledFontFaceKey, DesignFont>();

export function isDesignBundledFontFamily(value: string): value is DesignBundledFontFamily {
  return DESIGN_BUNDLED_FONT_FAMILIES.includes(value as DesignBundledFontFamily);
}

export function designBundledFontWeights(
  family: DesignBundledFontFamily,
): readonly DesignBundledFontWeight[] {
  return DESIGN_BUNDLED_FONT_CATALOG.find((entry) => entry.family === family)?.weights ?? [];
}

export function designBundledFontForStyle(
  family: DesignBundledFontFamily,
  weight: DesignBundledFontWeight,
): DesignFont | null {
  const key = designBundledFontFaceKey(family, weight);
  const data = FACE_DATA.get(key);
  if (!data) return null;
  const cached = FONT_CACHE.get(key);
  if (cached) return cached;
  const font = create(decodeBase64(data.base64));
  FONT_CACHE.set(key, font);
  return font;
}

/** Backward-compatible Sans face lookup. */
export function designBundledFont(weight: 400 | 700): DesignFont {
  const font = designBundledFontForStyle(DESIGN_BUNDLED_FONT_FAMILY, weight);
  if (!font) throw new Error(`Bundled Sans weight ${weight} is unavailable.`);
  return font;
}

/**
 * Embed each complete canonical face used by the document exactly once. Numeric
 * keys remain accepted for the former Sans-only API.
 */
export function designBundledFontFaceCss(
  usage: ReadonlyMap<DesignBundledFontFaceKey | 400 | 700, string>,
): string {
  const used = new Set<DesignBundledFontFaceKey>();
  for (const [key, text] of usage) {
    if (!text.length) continue;
    used.add(typeof key === "number"
      ? designBundledFontFaceKey(DESIGN_BUNDLED_FONT_FAMILY, key)
      : key);
  }
  return [...FACE_DATA]
    .filter(([key]) => used.has(key))
    .map(([, face]) => `@font-face{font-family:${JSON.stringify(face.family)};font-style:normal;font-weight:${face.weight};src:url(data:font/ttf;base64,${face.base64}) format("truetype")}`)
    .join("");
}
